import { z } from 'zod';
import raw from '@data/nuclear_kntt.json';
import {
  loadDataset,
  LocalizedTextSchema,
  ReviewStatusSchema,
  type Source,
} from '@/core/data/dataset';

/**
 * Vật lí 12 KNTT Chương IV "Vật lí hạt nhân" (Bài 21–23): data/nuclear_kntt.json, generated by
 * scripts/data/gen_nuclear_kntt.py (review pending, DATA_REVIEW VL12-NUC-1). The isotopes of Bảng
 * 23.2 are the dataset's items; the rest is the book's other tables, constants and questions.
 */
const IsotopeSchema = z.object({
  id: z.string().min(1),
  name: LocalizedTextSchema,
  symbol: z.string().min(1),
  Z: z.number().int().positive(),
  A: z.number().int().positive(),
  half_life: z.number().positive(),
  unit: z.enum(['second', 'day', 'year']),
  review_status: ReviewStatusSchema,
});
const ExtraSchema = z.object({
  particles: z.object({
    proton_kg: z.number(),
    neutron_kg: z.number(),
    elementary_charge: z.number(),
    amu_kg: z.number(),
    proton_amu: z.number(),
    neutron_amu: z.number(),
  }),
  radius_r0: z.number(),
  table_21_1: z.array(
    z.object({
      symbol: z.string(),
      name: LocalizedTextSchema,
      Z: z.number(),
      A: z.number(),
      atom_radius: z.number(),
      nucleus_radius: z.number(),
    }),
  ),
  masses: z.array(
    z.object({
      symbol: z.string(),
      Z: z.number(),
      A: z.number(),
      amu: z.number(),
      page: z.number(),
    }),
  ),
  fission_mev: z.number(),
  fusion_dd_mev: z.number(),
  critical_kg: z.record(z.string(), z.number()),
  counts_23_1: z.array(z.number().int().nonnegative()),
  curie_bq: z.number(),
  exposure: z.array(z.object({ id: z.string(), name: LocalizedTextSchema, percent: z.number() })),
  dose: z.object({
    background_mSv: z.number(),
    public_mSv: z.number(),
    learner_16_18_mSv: z.number(),
    worker_mSv: z.number(),
  }),
  examples: z.array(z.looseObject({ id: z.string(), lesson: z.number(), page: z.number() })),
});

const dataset = loadDataset('nuclear_kntt', IsotopeSchema, raw);
const extra = ExtraSchema.parse(raw);

export type Isotope = z.infer<typeof IsotopeSchema>;
export const ISOTOPES: readonly Isotope[] = dataset.items;
export const NUCLEAR_SOURCE: Source = dataset.source;
export const PARTICLES = extra.particles;
export const RADIUS_R0 = extra.radius_r0;
export const TABLE_21_1 = extra.table_21_1;
export const BOOK_MASSES = extra.masses;
export const FISSION_MEV = extra.fission_mev;
export const FUSION_DD_MEV = extra.fusion_dd_mev;
export const CRITICAL_KG = extra.critical_kg;
export const COUNTS_23_1 = extra.counts_23_1;
export const CURIE_BQ = extra.curie_bq;
export const EXPOSURE = extra.exposure;
export const DOSE = extra.dose;
export const EXAMPLES = extra.examples;

export const isotope = (id: string): Isotope => {
  const i = ISOTOPES.find((x) => x.id === id);
  if (!i) throw new Error(`no isotope ${id}`);
  return i;
};
